-- =============================================================================
-- 银龄伴诊 —— 种子数据（演示 / 答辩用）
-- -----------------------------------------------------------------------------
-- 版本      : V2
-- 覆盖模块  : M1 数据库设计与数据初始化
-- 生成方式  : 由脚本按固定随机种子生成，可复现；请勿手工零散修改
--
-- 规模：20 张表全部灌入，每张业务表行数 >= 30。
-- 边界场景覆盖：
--   1. 空字段        —— 部分老人无身份证/无手机号/无过敏史，部分订单无备注
--   2. 超长文本      —— 病史备注、服务小结、投诉内容接近字段上限
--   3. 非常用药      —— 药品字典含罕见病用药（吡非尼酮）且 is_common = 0
--   4. 跨天用药      —— 用药计划含 00:30 / 22:00 等跨零点时间点
--   5. 长期用药      —— end_date 为 NULL 表示长期服药
--   6. 漏服补记      —— 服药任务含 MISSED 与 was_missed = 1（补记）两种
--   7. 资质非通过态  —— 陪诊员含 PENDING / REJECTED / 健康证过期
--
-- 种子账号统一密码：Nl@123456（BCrypt 已入库，可直接登录）
-- =============================================================================

SET NAMES utf8mb4;

-- 便于重复演示：先清空业务表，再重新灌入（顺序与外键无关，本库未建物理外键）
-- 若只想增量追加，可注释掉下面这段 TRUNCATE。
TRUNCATE TABLE `sys_user`;
TRUNCATE TABLE `sys_login_log`;
TRUNCATE TABLE `sys_dict`;
TRUNCATE TABLE `sys_file`;
TRUNCATE TABLE `admin_oper_log`;
TRUNCATE TABLE `elder_profile`;
TRUNCATE TABLE `family_elder_relation`;
TRUNCATE TABLE `companion_audit_record`;
TRUNCATE TABLE `companion_profile`;
TRUNCATE TABLE `companion_order`;
TRUNCATE TABLE `order_status_log`;
TRUNCATE TABLE `order_reject_log`;
TRUNCATE TABLE `order_checkin`;
TRUNCATE TABLE `companion_track`;
TRUNCATE TABLE `medicine_dict`;
TRUNCATE TABLE `medication_plan`;
TRUNCATE TABLE `medication_task`;
TRUNCATE TABLE `order_review`;
TRUNCATE TABLE `complaint`;
TRUNCATE TABLE `internal_message`;

