-- =============================================================================
-- 18. complaint —— 投诉（32 条：待处理 / 处理中 / 已结案 / 已驳回 全覆盖）
--     不物理删除；状态只可正向流转
-- =============================================================================
INSERT INTO `complaint`
  (`id`,`order_id`,`order_no`,`complainant_id`,`complainant_role`,`target_user_id`,
   `target_role`,`type`,`content`,`evidence`,`status`,`handle_admin_id`,`handle_result`,
   `penalty_to_target`,`handle_time`,`create_time`) VALUES
  (31001, 1019, 'NL20260905000019', 319, 'COMPANION', 119, 'FAMILY', 'LATE', '陪诊员比约定时间晚了 40 分钟到达，导致老人错过取号，只能重新排队等候。', '["/uploads/202609/cp01.png"]', 'PENDING', NULL, NULL, 0, NULL, '2026-09-05 19:00:00'),
  (31002, 1020, 'NL20260906000020', 120, 'FAMILY', 320, 'COMPANION', 'ATTITUDE', '陪诊过程中态度不好，老人反复问路时显得很不耐烦，中途还一直低头看手机。', NULL, 'PENDING', NULL, NULL, 0, NULL, '2026-09-06 19:01:00'),
  (31003, 1021, 'NL20260907000021', 121, 'FAMILY', 321, 'COMPANION', 'INCOMPLETE', '约定要协助取药并送到家，实际只送到医院门口就走了，药品由老人自己拎回家。', NULL, 'PENDING', NULL, NULL, 0, NULL, '2026-09-07 19:02:00'),
  (31004, 1022, 'NL20260908000022', 322, 'COMPANION', 122, 'FAMILY', 'FEE_DISPUTE', '陪诊员全程几乎都在低头玩手机，没有陪同老人进入诊室，医生交代的复诊时间和注意事项一句都没有转达给家属；取药时还把两种药的名字看错，把降压药和降糖药的位置弄反，幸亏老人家属自己核对时及时发现，否则后果不堪设想；排队缴费期间擅自离开，让 82 岁的老人独自在缴费窗口前站了近二十分钟，期间老人因为不熟悉流程来回走了三趟；更严重的是，该陪诊员把老人的检查报告和病历本拍下来发到了自己的微信群里，照片中姓名、身份证号、诊断信息、住院号全都清晰可见，完全没有做任何遮挡处理，群里有几十个陌生人；家属在群里看到截图后立即要求删除，对方态度还很恶劣，说「又不是什么见不得人的病」，拒绝道歉；事后平台客服也未能给出有效的处理方案，只是说会「了解一下」。家属现已保存全部聊天记录、截图与通话录音作为证据，要求平台：一、对该陪诊员作出严肃处理并公示结果；二、就其泄露老人隐私的行为出具书面说明并承担相应责任；三、退还本次全部服务费；四、完善陪诊员的隐私保护培训与考核机制，避免其他老人遭遇同样的情况。', '["/uploads/202609/cp04.png"]', 'PENDING', NULL, NULL, 0, NULL, '2026-09-08 19:03:00'),
  (31005, 1023, 'NL20260909000023', 123, 'FAMILY', 323, 'COMPANION', 'PRIVACY', '发现陪诊员把老人的病历照片发在了自己的微信朋友圈，未做任何打码处理。', NULL, 'PENDING', NULL, NULL, 0, NULL, '2026-09-09 19:04:00'),
  (31006, 1024, 'NL20260910000024', 124, 'FAMILY', 324, 'COMPANION', 'OTHER', '陪诊员临时更换了人员，来的不是下单时约定的那位，事先也没有通知家属。', NULL, 'PENDING', NULL, NULL, 0, NULL, '2026-09-10 19:05:00'),
  (31007, 1025, 'NL20260911000025', 301, 'COMPANION', 125, 'FAMILY', 'LATE', '陪诊员比约定时间晚了 40 分钟到达，导致老人错过取号，只能重新排队等候。', '["/uploads/202609/cp01.png"]', 'PENDING', NULL, NULL, 0, NULL, '2026-09-11 19:06:00'),
  (31008, 1026, 'NL20260912000026', 126, 'FAMILY', 302, 'COMPANION', 'ATTITUDE', '陪诊过程中态度不好，老人反复问路时显得很不耐烦，中途还一直低头看手机。', NULL, 'PENDING', NULL, NULL, 0, NULL, '2026-09-12 19:07:00'),
  (31009, 1027, 'NL20260913000027', 127, 'FAMILY', 303, 'COMPANION', 'INCOMPLETE', '约定要协助取药并送到家，实际只送到医院门口就走了，药品由老人自己拎回家。', NULL, 'PENDING', NULL, NULL, 0, NULL, '2026-09-13 19:08:00'),
  (31010, 1028, 'NL20260914000028', 304, 'COMPANION', 128, 'FAMILY', 'FEE_DISPUTE', '线下结算时要求多付 50 元，说是加班费，但下单时并未说明有这笔费用。', '["/uploads/202609/cp04.png"]', 'PENDING', NULL, NULL, 0, NULL, '2026-09-14 19:09:00'),
  (31011, 1029, 'NL20260818000029', 129, 'FAMILY', 305, 'COMPANION', 'PRIVACY', '发现陪诊员把老人的病历照片发在了自己的微信朋友圈，未做任何打码处理。', NULL, 'PROCESSING', 1, NULL, 0, NULL, '2026-09-05 19:10:00'),
  (31012, 1030, 'NL20260819000030', 130, 'FAMILY', 306, 'COMPANION', 'OTHER', '陪诊员临时更换了人员，来的不是下单时约定的那位，事先也没有通知家属。', NULL, 'PROCESSING', 1, NULL, 0, NULL, '2026-09-06 19:11:00'),
  (31013, 1031, 'NL20260820000031', 307, 'COMPANION', 101, 'FAMILY', 'LATE', '陪诊员比约定时间晚了 40 分钟到达，导致老人错过取号，只能重新排队等候。', '["/uploads/202609/cp01.png"]', 'PROCESSING', 1, NULL, 0, NULL, '2026-09-07 19:12:00'),
  (31014, 1032, 'NL20260821000032', 102, 'FAMILY', 308, 'COMPANION', 'ATTITUDE', '陪诊过程中态度不好，老人反复问路时显得很不耐烦，中途还一直低头看手机。', NULL, 'PROCESSING', 1, NULL, 0, NULL, '2026-09-08 19:13:00'),
  (31015, 1033, 'NL20260822000033', 103, 'FAMILY', 309, 'COMPANION', 'INCOMPLETE', '约定要协助取药并送到家，实际只送到医院门口就走了，药品由老人自己拎回家。', NULL, 'PROCESSING', 1, NULL, 0, NULL, '2026-09-09 19:14:00'),
  (31016, 1034, 'NL20260823000034', 310, 'COMPANION', 104, 'FAMILY', 'FEE_DISPUTE', '线下结算时要求多付 50 元，说是加班费，但下单时并未说明有这笔费用。', '["/uploads/202609/cp04.png"]', 'PROCESSING', 1, NULL, 0, NULL, '2026-09-10 19:15:00'),
  (31017, 1035, 'NL20260824000035', 105, 'FAMILY', 311, 'COMPANION', 'PRIVACY', '发现陪诊员把老人的病历照片发在了自己的微信朋友圈，未做任何打码处理。', NULL, 'RESOLVED', 1, '经核实情况属实，已对陪诊员进行警告并扣减信用分，同时向投诉人致歉并说明后续改进措施。', 1, '2026-09-13 10:16:00', '2026-09-11 19:16:00'),
  (31018, 1036, 'NL20260825000036', 106, 'FAMILY', 312, 'COMPANION', 'OTHER', '陪诊员临时更换了人员，来的不是下单时约定的那位，事先也没有通知家属。', NULL, 'RESOLVED', 1, '经核实情况属实，已对陪诊员进行警告并扣减信用分，同时向投诉人致歉并说明后续改进措施。', 1, '2026-09-13 10:17:00', '2026-09-12 19:17:00'),
